```js
backofficeRegistry: {
    availability: {
        refreshIntervalMs: 10000,
        failureRetryIntervalMs: 5000,
        failureBackoffMultiplier: 2,
        maxFailureBackoffMs: 60000
    }
}
```

```js
module.exports = {
    backofficeRegistry: {
        audit: {
            enabled: true,
            failClosed: true,
            requireAcknowledgement: true,
            publisherService: 'EnvironmentBackofficeAuditPublisher'
        },
        store: {
            mode: 'distributed',
            moduleName: 'backoffice',
            engineName: 'redis',
            keyPrefix: 'replace-with-environment-owned-prefix:'
        },
        operations: {
            requireDistributedStore: true,
            production: {
                enabled: true,
                requireHttpsOnly: true,
                requireHostAllowlists: true,
                requireStrictAudit: true,
                requireStrictAlerts: true
            },
            alerts: {
                enabled: true,
                failClosed: true,
                requireAcknowledgement: true,
                publisherService: 'EnvironmentBackofficeAlertPublisher'
            },
            minimumSamples: 20,
            thresholds: {
                availabilityFailurePercent: 20,
                availabilityQueuePercent: 70,
                discoveryFailurePercent: 20,
                storeErrors: 1,
                conditionalDeleteConflicts: 10,
                refreshThrottles: 1
            }
        }
    }
};
```

```js
module.exports = {
    backofficeRegistry: {
        store: {
            mode: 'distributed',
            moduleName: 'backoffice',
            engineName: 'redis',
            keyPrefix: 'registry:lease:'
        }
    },
    cache: {
        backoffice: {
            engines: {
                redis: {
                    enabled: true,
                    options: { url: process.env.NODICS_CACHE_REDIS_URL }
                }
            }
        }
    }
};
```
